from itertools import combinations

# We need to partition {1, 2, ..., 19} into 5 subsets, each summing to 38
# Let's use a backtracking approach

def solve():
    numbers = list(range(1, 20))
    target = 38
    num_subsets = 5

    # assignment[i] = which subset (0-4) number i+1 belongs to
    assignment = [-1] * 19
    subset_sums = [0] * 5

    def backtrack(idx):
        if idx == 19:
            # Check if all subsets sum to 38
            return all(s == target for s in subset_sums)

        num = idx + 1  # The actual number (1-indexed)

        for subset in range(num_subsets):
            if subset_sums[subset] + num <= target:
                assignment[idx] = subset
                subset_sums[subset] += num

                if backtrack(idx + 1):
                    return True

                subset_sums[subset] -= num
                assignment[idx] = -1

        return False

    if backtrack(0):
        return assignment
    return None

result = solve()
print("Result:", result)
if result:
    # Verify the solution
    subsets = [[] for _ in range(5)]
    for i, subset in enumerate(result):
        subsets[subset].append(i + 1)

    for i, subset in enumerate(subsets):
        print(f"Subset {i}: {subset}, sum = {sum(subset)}")
